for (const t of targets) {
  let html = fs.readFileSync(t.path, 'utf8');
  if (html.includes(t.categoryOld)) html = html.replace(t.categoryOld, t.categoryNew);
  else if (t.categoryFallback && t.categoryFallback.test(html)) html = html.replace(t.categoryFallback, t.categoryNew);

  const re = /<div class="conditional-panel" data-panel="art" hidden="">[\s\S]*?<\/div>\s*<div class="conditional-panel" data-panel="event" hidden="">/;
  if (!re.test(html)) throw new Error(`Art panel not found in ${t.path}`);
  html = html.replace(re, `${t.artBlock}\n<div class="conditional-panel" data-panel="event" hidden="">`);
  fs.writeFileSync(t.path, html);
}

